# এসএসসি উচ্চতর গণিত অধ্যায় ৭ (অসীম ধারা), ৮ (ত্রিকোণমিতি), ৯ (সূচকীয় ও লগারিদমীয় ফাংশন): প্রতি অনুশীলনী ৩০টি
from sqlib import *
import sympy as sp, math
x,y,n,t,a,b,c=sp.symbols('x y n t a b c'); R=sp.Rational; pi=sp.pi; cl=math.isclose; s2,s3=sp.sqrt(2),sp.sqrt(3)
th=sp.symbols('th')
def T(e,lo=0,hi=2*pi): return sorted(sp.solveset(e,th,sp.Interval.Ropen(lo,hi)),key=float)
G=lambda a_,r_: a_/(1-r_)
# ---- 7 ----
assert G(1,R(1,3))==R(3,2) and G(8,R(-1,2))==R(16,3) and G(R(3,10),R(1,10))==R(1,3) and rec(0,'1','7')==F(8,45) and rec(1,'','24')==F(41,33)
assert sp.solve(8/(1-x)-12,x)==[R(1,3)] and 15*(1-R(2,5))==9 and G(4,R(1,4))==R(16,3) and sp.limit(sp.summation(1/((2*n-1)*(2*n+1)),(n,1,t)),t,sp.oo)==R(1,2)
assert sp.simplify(sp.summation(1/((2*n-1)*(2*n+1)),(n,1,t))-t/(2*t+1))==0 and sp.summation(1/(n*(n+1)),(n,2,sp.oo))==R(1,2) and 10+2*G(R(15,2),R(3,4))==70 and G(64,R(1,2))==128
assert [k*k+1 for k in range(1,5)]==[2,5,10,17] and R(9,7)==R(2*5-1,5+2) and sp.solve(9*(2*n-1)-13*(n+2),n)==[7] and sp.solve(n/(n+2)-R(3,5),n)==[3] and G(3,R(1,4))==4 and 3*R(1,4)==R(3,4)
assert G(6,R(1,3))==9 and sp.solve(1/(1-x)-3,x)==[R(2,3)] and sp.solve([a/(1-x)-20,a**2/(1-x**2)-100],[a,x])==[(8,R(3,5))] and F(45,99)+F(54,99)==1 and rec(2,'','1')==F(19,9)
assert sum(int('1'*k) for k in range(1,4))==(10**4-10-27)//81 and G(R(7,10),R(1,10))==R(7,9) and sp.solve(1-x/(1-x),x)==[R(1,2)]
